<script>
 import {onDestroy} from 'svelte';
 import {Upload,FileText,Check,AlertCircle,ArrowRight,Plus} from 'lucide-svelte';
 import {analyzeStoryText,inspectStory} from '../story-import.js';
 let {oncreate,oncancel}=$props();
 let draft=$state(null),file=$state(null),document=$state(null),busy=$state(false),progress=$state(''),error=$state(''),tab=$state('scenes'),saving=$state(false);
 let controller;
 let gaps=$derived(draft?inspectStory(draft):[]);
 onDestroy(()=>{controller?.abort();for(const image of document?.images||[])if(image.preview)URL.revokeObjectURL(image.preview);});
 async function read(e){file=e.currentTarget.files?.[0];if(!file)return;busy=true;error='';draft=null;document=null;controller?.abort();controller=new AbortController();try{const {readStoryPdf}=await import('../pdf-import.js');document=await readStoryPdf(file,p=>progress=`Reading page ${p.current} of ${p.total}`,controller.signal);if(!document.text.trim())throw Error('No selectable text was found. This appears to be a scanned PDF. Run OCR or import a text-based PDF; no story has been invented.');for(const image of document.images||[])image.preview=URL.createObjectURL(image.file);draft=analyzeStoryText(document.text,file.name.replace(/\.pdf$/i,''));}catch(e){error=e.message;}finally{busy=false;}}
 function add(kind){const list=draft[kind];list.push({id:'draft-'+crypto.randomUUID(),name:'',description:'',appearance:'',personality:'',clothing:'',selected:true,evidence:'Added during review'});}
 function toggleCast(s,id){s.characterIds=s.characterIds.includes(id)?s.characterIds.filter(x=>x!==id):[...s.characterIds,id];}
 function assignImage(image,value){
  if(image.assigned){const [kind,id]=image.assigned.split(':');const list=kind==='scene'?draft.scenes:kind==='character'?draft.characters:kind==='location'?draft.locations:draft.themes;const item=list.find(x=>String(x.id)===id);if(item?.importFile===image.file)item.importFile=null;}
  image.assigned=value;if(!value)return;const [kind,id]=value.split(':');const list=kind==='scene'?draft.scenes:kind==='character'?draft.characters:kind==='location'?draft.locations:draft.themes;const item=list.find(x=>String(x.id)===id);if(item)item.importFile=image.file;
 }
 function picture(e,item){item.importFile=e.currentTarget.files?.[0]||null;}
 async function save(){if(!draft.title.trim()||!draft.scenes.length){error='Add a story title and at least one scene.';return;}if([...draft.characters,...draft.locations,...draft.themes].some(x=>!x.name.trim())){error='Name each record or remove the empty record.';return;}saving=true;error='';try{await oncreate({...draft,mode:'pdf',sourceDocument:document,sourceFile:file,importGaps:gaps});}catch(e){error=e.message;}finally{saving=false;}}
</script>
<section class="pdf-import" aria-label="Import a story PDF">
 <div class="import-intro"><FileText size={27}/><div><h2>Your manuscript, connected.</h2><p>Read the whole PDF, review its story records, then open a connected canvas.</p></div></div>
 <label class="pdf-drop"><Upload size={25}/><strong>{file?.name||'Choose your story PDF'}</strong><span>Text-based PDF · up to 40 MB and 500 pages</span><input aria-label="Upload story PDF" type="file" accept="application/pdf,.pdf" disabled={busy||saving} onchange={read}/></label>
 {#if busy}<div class="import-progress" role="status"><span class="import-spinner"></span>{progress||'Opening document…'}<button class="text-button" onclick={()=>controller.abort()}>Cancel reading</button></div>{/if}
 {#if error}<p class="director-error" role="alert">{error}</p>{/if}
 {#if draft}
 <div class="import-summary"><span><Check size={16}/>{document.pageCount} pages read</span><span>{draft.scenes.length} scenes</span><span>{draft.characters.length} characters</span><span>{draft.locations.length} locations</span><span>{gaps.length} details to review</span></div>
 <p class="import-disclosure">Source-based extraction, not language-model analysis. Names, scene headings, quoted dialogue and explicitly stated emotions are proposed for your review. Interpretations can be corrected before saving. No image generation runs during import.</p>
 {#if document.scannedPages.length}<p class="reference-warning"><AlertCircle size={16}/>No readable text on pages {document.scannedPages.join(', ')}. These pages may be scans, illustrations or blank pages. Review the original PDF; OCR is not connected.</p>{/if}
 <label class="director-field">Story title<input bind:value={draft.title}/></label>
 <div class="import-tabs" role="tablist" aria-label="PDF review sections">{#each [['scenes','Scenes'],['characters','Characters'],['locations','Locations'],['themes','Themes'],['images','PDF images'],['missing','Missing details'],['source','Source pages']] as [key,label]}<button role="tab" aria-selected={tab===key} class:active={tab===key} onclick={()=>tab=key}>{label}{key==='missing'?' · '+gaps.length:''}</button>{/each}</div>
 <div class="import-review">
 {#if tab==='images'}<p>Assign extracted images to the correct record. A PDF picture is not assumed to be a character, location or scene until you choose.</p>{#each document.imageWarnings||[] as warning}<p class="reference-warning">{warning}</p>{/each}<div class="pdf-image-grid">{#each document.images||[] as image}<article><img src={image.preview} alt={'Image extracted from page '+image.page} loading="lazy"/><small>Page {image.page} · {image.width} × {image.height}</small><label class="director-field">Assign to<select value={image.assigned||''} onchange={e=>assignImage(image,e.currentTarget.value)}><option value="">Keep in original PDF only</option>{#each [['character',draft.characters],['location',draft.locations],['scene',draft.scenes],['theme',draft.themes]] as [kind,items]}<optgroup label={kind}>{#each items as item}<option value={kind+':'+item.id}>{item.name||item.title}</option>{/each}</optgroup>{/each}</select></label></article>{:else}<p>No extractable embedded images were found. You can upload references individually in the character, location and scene tabs.</p>{/each}</div>
 {:else if tab==='source'}{#each document.pages as page}<details><summary>Page {page.number} · {page.textFound?'Text extracted':'Needs review'}</summary><pre class="source-page">{page.text||'No selectable text on this page.'}</pre></details>{/each}
 {:else if tab==='missing'}<p>Missing details stay as drafts. You can finish them now or use Import / Generate inside the story library after opening the canvas.</p>{#each gaps as gap}<button class="import-gap" onclick={()=>tab=gap.type==='character'?'characters':gap.type==='location'?'locations':gap.type==='scene'?'scenes':'themes'}><AlertCircle size={15}/><span><strong>{gap.label}</strong><small>{gap.detail}</small></span><ArrowRight size={15}/></button>{:else}<div class="empty-state"><Check size={24}/><h3>All required details are present.</h3><p>Review the story before creating your canvas.</p></div>{/each}
 {:else if tab==='scenes'}{#each draft.scenes as s,i}<details open={i===0}><summary>Scene {i+1} · {s.title} <span>{s.text.trim().split(/\s+/).filter(Boolean).length} words</span></summary><label class="director-field">Title<input bind:value={s.title}/></label><label class="director-field">Description<textarea bind:value={s.text}></textarea></label><fieldset class="import-cast"><legend>Characters in this moment</legend>{#each draft.characters as c}<label><input type="checkbox" checked={s.characterIds.includes(c.id)} onchange={()=>toggleCast(s,c.id)}/>{c.name}</label>{/each}</fieldset><label class="director-field">Location<select bind:value={s.locationId}><option value="">Not identified; add or select a location</option>{#each draft.locations as l}<option value={l.id}>{l.name}</option>{/each}</select></label><div class="import-field-grid"><label class="director-field">Actions<textarea bind:value={s.actions}></textarea></label><label class="director-field">Emotions<input bind:value={s.emotions}/></label></div>{#each s.emotionEvidence as evidence}<p class="import-evidence"><strong>{evidence.emotion}</strong> · {evidence.quote}</p>{/each}<label class="director-field">Dialogue<textarea bind:value={s.dialogue}></textarea></label><label class="import-file">Import this scene’s image<input type="file" accept="image/png,image/jpeg,image/webp" onchange={e=>picture(e,s)}/></label></details>{/each}
 {:else}{@const kind=tab}{#each draft[kind] as item,i}<details open={i===0}><summary>{item.name||'New '+kind.slice(0,-1)}<button class="text-button" aria-label={'Remove '+(item.name||kind)} onclick={e=>{e.preventDefault();draft[kind]=draft[kind].filter(x=>x.id!==item.id);}}>Remove</button></summary><p class="import-evidence">{item.confidence||'Added in review'}{item.evidence?' · '+item.evidence:''}</p><label class="director-field">Name<input bind:value={item.name}/></label><label class="director-field">Description<textarea bind:value={item.description}></textarea></label>{#if kind==='characters'}<div class="import-field-grid"><label class="director-field">Appearance<textarea bind:value={item.appearance}></textarea></label><label class="director-field">Personality<textarea bind:value={item.personality}></textarea></label></div><label class="director-field">Clothing<textarea bind:value={item.clothing}></textarea></label>{/if}<label class="import-file">Import {kind==='characters'?'portrait or reference sheet':kind==='locations'?'location reference':'theme moodboard'}<input type="file" accept="image/png,image/jpeg,image/webp" onchange={e=>picture(e,item)}/></label>{#if item.importFile}<p>{item.importFile.name} · saved when you create the story</p>{/if}</details>{/each}<button class="button secondary" onclick={()=>add(kind)}><Plus size={15}/>Add {kind==='characters'?'character':kind==='locations'?'location':'theme'}</button>{/if}
 </div>
 <div class="import-save-note"><strong>Save drafts without losing the source.</strong><p>The original PDF and full extracted text are kept on this device. Story records and missing details remain editable. Extracted PDF images can be assigned in the PDF images tab. Unassigned and unsupported images remain in the original document.</p></div>
 <div class="form-actions"><button class="button secondary" disabled={saving} onclick={oncancel}>Cancel</button><button class="button primary" disabled={saving} onclick={save}>{saving?'Saving story and references…':'Save story & open canvas'}<ArrowRight size={15}/></button></div>
 {/if}
</section>
